#ifndef MEDIA_CELT_TABLES_H
#define MEDIA_CELT_TABLES_H

#include <stdint.h>

// Constant tables of the Opus CELT layer for the standard 48 kHz / 20 ms mode
// (generated by tools/gen_celt_tables.py from the RFC 6716 reference data).

#define CELT_NBANDS 21
#define CELT_NALLOC 11            // static allocation rows

extern const int16_t celt_eband5ms[CELT_NBANDS + 1];     // band edges in 2.5 ms-frame bins
extern const uint8_t celt_band_alloc[CELT_NALLOC * CELT_NBANDS];
extern const int16_t celt_logN[CELT_NBANDS];             // log2 of the band width, 1/8 bit units
extern const int16_t celt_cache_index[105];              // [(LM+1) * 21 + band] -> offset into cache_bits
extern const uint8_t celt_cache_bits[392];               // bits needed for 0..K pulses (1/8 bit)
extern const uint8_t celt_cache_caps[168];               // per band cap, [(2*LM + stereo) * 21 + band]
extern const float   celt_window120[120];                // the low-overlap window's rising half
extern const uint8_t celt_e_prob_model[4 * 2 * 42];      // [LM][intra][2 * band]
extern const float   celt_eMeans[25];

#endif
